import type { MetadataRoute } from "next";

/**
 * Installable PWA so the daily lands on players' home screens — the whole
 * point of a daily-rotation game. Icons are generated by scripts/og-image.mts.
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "Roughly Right — daily estimation games",
    short_name: "Roughly Right",
    description: "Five real-world estimates a day. Get closer to earn more points. New puzzle at 00:00 UTC.",
    start_url: "/estimation",
    display: "standalone",
    background_color: "#060a17",
    theme_color: "#060a17",
    icons: [
      { src: "/icon-192.png", sizes: "192x192", type: "image/png" },
      { src: "/icon-512.png", sizes: "512x512", type: "image/png" },
    ],
  };
}
